/* Instagram DNA — gallery white, hairline borders, gradient pink to purple */
.theme-instagram-dna {
  --bg: oklch(1.000 0 0);
  --surface: oklch(1.000 0 0);
  --surface-2: oklch(0.985 0 0);
  --fg: oklch(0.269 0 0);
  --fg-muted: oklch(0.647 0 0);
  --accent: oklch(0.605 0.213 6.8);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.504 0.188 308.6);
  --line: oklch(0.891 0 0);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.810 0.148 71.1);
  --danger: oklch(0.641 0.200 20.5);
  --radius: 0.75rem;
  --radius-sm: 0.5rem;
  --radius-lg: 1rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 2px color-mix(in oklab, oklch(0.6 0.2 350) 50%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Sen", sans-serif;
  --font-body: "Sen", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: -0.01em;
  --label-transform: none;
  --label-tracking: 0.05em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-instagram-dna h1,
.theme-instagram-dna h2,
.theme-instagram-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
